<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ShelterCareLog extends Model { protected $fillable=['adoption_listing_id','shelter_id','created_by','logged_at','category','notes']; protected $casts=['logged_at'=>'datetime']; public function listing(){return $this->belongsTo(AdoptionListing::class,'adoption_listing_id');} public function shelter(){return $this->belongsTo(Shelter::class);} public function creator(){return $this->belongsTo(User::class,'created_by');} }